package propertyrental.platform.location.application.mapper;

import org.springframework.stereotype.Component;

import propertyrental.platform.location.api.dto.request.CreateSuburbRequest;
import propertyrental.platform.location.api.dto.request.UpdateSuburbRequest;
import propertyrental.platform.location.api.dto.response.SuburbResponse;
import propertyrental.platform.location.infrastructure.persistence.entity.SuburbEntity;

@Component
public class SuburbMapper {

    // This build a new entity from a create request (the id is generated by the database)
    public SuburbEntity toEntity(CreateSuburbRequest request) {
        SuburbEntity suburb = new SuburbEntity();
        suburb.setCityId(request.cityId());
        suburb.setName(request.name());

        return suburb;
    }

    // This applies an update request to an existing entity in place
    public void updateEntity(SuburbEntity suburb, UpdateSuburbRequest request) {
        suburb.setCityId(request.cityId());
        suburb.setName(request.name());
    }

    // This one convert an entity to the response DTO so that the entity is never exposed
    public SuburbResponse toResponse(SuburbEntity suburb) {

        return new SuburbResponse(suburb.getId(), suburb.getCityId(), suburb.getName());
    }
}